;;
; @file   script_02.asm
; @brief  Saturday NPC schedule (variant of script_01) for the town, the mayor's house, the church, the woods and the mine.
;         Started as group $02 by the fAreaEvents_* handlers when nCurrentWeekdayID is 6; the slots mirror script_01 with
;         the villagers' Saturday positions and conversations.
; @bank   $B3   (AI byte code; script id $02, slot table generated by tools/ai/aidata.py from defs/ai/scripts.json)
; @see    script_01 script_03 docs/ai/commands.md
;;



    incsrc "../../../../build/gen/ai/slots_02.asm"
 
