    %AICMD0x11_EnableUserControl()                             ;B3AE23
    %AICMD0x15_JumpIfEquals8(nCurrentSeasonID, 2, pAIScripting0x02_Town_IfCurrentSeasonIDIs2)     ;B3AE24
